    def load_splitter(self,inp_file_location):
            
            with PIL.Image.open(inp_file_location) as thumb_temp:
                if thumb_temp.mode=="RGBA" or thumb_temp.mode=="RGB":
                    thumb_temp=PIL.ImageChops.convert("L")
